const fs = require('fs');
const d = require('docx');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, ShadingType, AlignmentType, HeadingLevel, BorderStyle,
  PageBreak, LevelFormat, convertInchesToTwip
} = d;

const GOLD = 'A8894F';
const DARK = '1A1A1A';
const GREY = '5C5C5C';
const CREAM = 'F5F2EC';
const LIGHT = 'EDEAE3';

const FONT = 'Calibri';

// ---------- helpers ----------
const rule = (color = GOLD, size = 8) => new Paragraph({
  spacing: { before: 60, after: 200 },
  border: { bottom: { style: BorderStyle.SINGLE, size, color } },
});

const p = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after ?? 140, line: 276 },
  alignment: opts.align,
  indent: opts.indent,
  children: [new TextRun({
    text,
    font: FONT,
    size: opts.size ?? 21,
    bold: opts.bold ?? false,
    italics: opts.italics ?? false,
    color: opts.color ?? DARK,
  })],
});

const sectionHead = (num, text) => new Paragraph({
  spacing: { before: 360, after: 60 },
  keepNext: true,
  border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD } },
  children: [
    new TextRun({ text: num + '   ', font: FONT, size: 22, bold: true, color: GOLD }),
    new TextRun({ text: text.toUpperCase(), font: FONT, size: 22, bold: true, color: DARK, characterSpacing: 30 }),
  ],
});

const subHead = (text) => new Paragraph({
  spacing: { before: 220, after: 100 },
  keepNext: true,
  children: [new TextRun({ text, font: FONT, size: 21, bold: true, color: DARK })],
});

const bullet = (text, bold) => new Paragraph({
  numbering: { reference: 'lux-bullets', level: 0 },
  spacing: { after: 70, line: 264 },
  children: bold
    ? [new TextRun({ text: bold, font: FONT, size: 20, bold: true, color: DARK }),
       new TextRun({ text: text, font: FONT, size: 20, color: DARK })]
    : [new TextRun({ text, font: FONT, size: 20, color: DARK })],
});

const cellPara = (text, opts = {}) => new Paragraph({
  spacing: { before: 60, after: 60, line: 252 },
  alignment: opts.align,
  children: [new TextRun({
    text,
    font: FONT,
    size: opts.size ?? 19,
    bold: opts.bold ?? false,
    color: opts.color ?? DARK,
  })],
});

const TW = 9360; // table width for Letter with 1" margins

function makeTable(cols, headers, rows, headerFill) {
  const headRow = new TableRow({
    tableHeader: true,
    children: headers.map((h, i) => new TableCell({
      width: { size: cols[i], type: WidthType.DXA },
      shading: { type: ShadingType.CLEAR, fill: headerFill || DARK, color: 'auto' },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [cellPara(h.toUpperCase(), { bold: true, color: 'FFFFFF', size: 17 })],
    })),
  });
  const bodyRows = rows.map((r, ri) => new TableRow({
    children: r.map((c, i) => new TableCell({
      width: { size: cols[i], type: WidthType.DXA },
      shading: { type: ShadingType.CLEAR, fill: ri % 2 ? CREAM : 'FFFFFF', color: 'auto' },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [cellPara(c, { bold: i === 0 })],
    })),
  }));
  return new Table({
    columnWidths: cols,
    width: { size: TW, type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
      bottom: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
      left: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
      right: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
      insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
      insideVertical: { style: BorderStyle.SINGLE, size: 2, color: LIGHT },
    },
    rows: [headRow, ...bodyRows],
  });
}

// Option card: full-width single cell block
function optionCard(tag, title, price, cadence, blurb, items, bestFor, highlight) {
  const kids = [
    new Paragraph({
      spacing: { after: 40 },
      children: [new TextRun({ text: tag.toUpperCase(), font: FONT, size: 16, bold: true, color: GOLD, characterSpacing: 40 })],
    }),
    new Paragraph({
      spacing: { after: 40 },
      children: [new TextRun({ text: title, font: FONT, size: 26, bold: true, color: DARK })],
    }),
    new Paragraph({
      spacing: { after: 120 },
      children: [
        new TextRun({ text: price, font: FONT, size: 24, bold: true, color: DARK }),
        new TextRun({ text: '  ' + cadence, font: FONT, size: 18, color: GREY }),
      ],
    }),
    new Paragraph({
      spacing: { after: 120, line: 264 },
      children: [new TextRun({ text: blurb, font: FONT, size: 19, italics: true, color: GREY })],
    }),
  ];
  items.forEach(it => kids.push(new Paragraph({
    numbering: { reference: 'lux-bullets', level: 0 },
    spacing: { after: 60, line: 252 },
    children: [new TextRun({ text: it, font: FONT, size: 19, color: DARK })],
  })));
  kids.push(new Paragraph({
    spacing: { before: 140, after: 20 },
    children: [
      new TextRun({ text: 'Best for: ', font: FONT, size: 19, bold: true, color: DARK }),
      new TextRun({ text: bestFor, font: FONT, size: 19, color: DARK }),
    ],
  }));

  return new Table({
    columnWidths: [TW],
    width: { size: TW, type: WidthType.DXA },
    borders: {
      top: { style: BorderStyle.SINGLE, size: 6, color: highlight ? GOLD : LIGHT },
      bottom: { style: BorderStyle.SINGLE, size: 6, color: highlight ? GOLD : LIGHT },
      left: { style: BorderStyle.SINGLE, size: highlight ? 18 : 6, color: highlight ? GOLD : LIGHT },
      right: { style: BorderStyle.SINGLE, size: 6, color: highlight ? GOLD : LIGHT },
    },
    rows: [new TableRow({
      cantSplit: false,
      children: [new TableCell({
        width: { size: TW, type: WidthType.DXA },
        shading: { type: ShadingType.CLEAR, fill: highlight ? CREAM : 'FFFFFF', color: 'auto' },
        margins: { top: 200, bottom: 200, left: 220, right: 220 },
        children: kids,
      })],
    })],
  });
}

const spacer = (h) => new Paragraph({ spacing: { after: h ?? 200 }, children: [new TextRun({ text: '', font: FONT, size: 12 })] });

// ---------- content ----------
const children = [];

// COVER
children.push(new Paragraph({
  spacing: { before: 1400, after: 40 },
  children: [new TextRun({ text: 'THE LUXORA COLLECTIVE', font: FONT, size: 40, bold: true, color: DARK, characterSpacing: 60 })],
}));
children.push(rule(GOLD, 12));
children.push(new Paragraph({
  spacing: { before: 240, after: 60 },
  children: [new TextRun({ text: 'Growth Partnership Proposal', font: FONT, size: 32, color: DARK })],
}));
children.push(new Paragraph({
  spacing: { after: 500 },
  children: [new TextRun({ text: 'Continuation of Engagement', font: FONT, size: 22, italics: true, color: GOLD })],
}));
children.push(p('Prepared for', { size: 18, color: GREY, after: 40 }));
children.push(p('Dr. Carl Hyder', { size: 26, bold: true, after: 20 }));
children.push(p('Aesthetic Renewal Med Spa', { size: 22, after: 20 }));
children.push(p('Medford and Cinnaminson', { size: 20, color: GREY, after: 500 }));
children.push(p('Prepared by', { size: 18, color: GREY, after: 40 }));
children.push(p('Bethany Ward, Co-Founder & CEO', { size: 20, bold: true, after: 20 }));
children.push(p('The Luxora Collective  |  theluxoracollective.co', { size: 19, color: GREY, after: 20 }));
children.push(p('July 2026', { size: 19, color: GREY, after: 0 }));
children.push(new Paragraph({ children: [new PageBreak()] }));

// 01 WHO WE ARE
children.push(sectionHead('01', 'Who We Are'));
children.push(p('The Luxora Collective is a premium revenue growth partner for independent med spas. We are not an agency that rents you leads and disappears when the contract ends.'));
children.push(p('We work from the inside out. Before we ask a practice to spend another dollar acquiring anything new, we find the revenue already sitting inside the building: undertrained front desks, unconverted consults, stagnant patients who have not been contacted in a year, missing memberships, weak package architecture. That is the Revenue Leak Audit, and it is where every Luxora engagement begins.'));
children.push(p('From there we deliver a full Market Blueprint, and only then do we install the growth engine: the right services, staff sales training, systems that run without the owner in every transaction, memberships, package architecture, AI follow-up, CRM, partnerships, a reputation engine, marketing, and lifetime value frameworks.'));
children.push(p('Everything is done with you, not to you. Knowledge transfer at every step. The goal is not for Aesthetic Renewal to depend on Luxora forever. The goal is for your team to be more capable, more confident, and more in control than they were the day we walked in.'));
children.push(spacer(80));
children.push(new Table({
  columnWidths: [TW],
  width: { size: TW, type: WidthType.DXA },
  borders: {
    top: { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' },
    bottom: { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' },
    left: { style: BorderStyle.SINGLE, size: 18, color: GOLD },
    right: { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' },
  },
  rows: [new TableRow({ children: [new TableCell({
    width: { size: TW, type: WidthType.DXA },
    shading: { type: ShadingType.CLEAR, fill: CREAM, color: 'auto' },
    margins: { top: 180, bottom: 180, left: 220, right: 220 },
    children: [
      new Paragraph({ spacing: { after: 0, line: 276 }, children: [new TextRun({
        text: 'Aesthetic Renewal is positioned to own a category no local competitor currently holds: physician-led, medical-grade aesthetics backed by decades of clinical credibility across both locations. The gap has never been clinical quality. The gap is visibility, and the systems that turn visibility into booked, retained, high-value patients.',
        font: FONT, size: 20, italics: true, color: DARK })] }),
    ],
  })] })],
}));

// 02 WHAT YOU PAID FOR
children.push(sectionHead('02', 'What You Engaged Us For'));
children.push(p('Aesthetic Renewal engaged The Luxora Collective for our Three Pillar Program at an investment of $9,000. That contract covered three defined deliverables.'));
children.push(spacer(60));
children.push(makeTable([1900, 4600, 2860],
  ['Pillar', 'Contracted Scope', 'Status'],
  [
    ['Revenue Leak Audit', 'Full diagnostic of where revenue was being lost across both locations: front desk conversion, consult close rate, patient reactivation, membership gaps, and package structure.', 'Delivered'],
    ['Market Blueprint', 'Competitive positioning analysis and a data-backed roadmap specific to Aesthetic Renewal\u2019s market, patient base, and physician-led credibility, built around the Aesthetic Renewal brand identity.', 'Delivered'],
    ['Playbook Delivery', 'Written, trainable frameworks handed to your team so results are transferable and not dependent on any one person.', 'Delivered'],
  ]));
children.push(spacer(120));
children.push(p('That was the contract. What follows is what actually happened.'));

// 03 ABOVE AND BEYOND
children.push(sectionHead('03', 'What We Actually Delivered'));
children.push(p('Every item below sits outside the contracted scope of work. None of it was billed. We delivered it because the strategy called for it and because we do not hand a practice a plan and walk away from the execution.'));
children.push(spacer(60));
children.push(makeTable([2700, 6660],
  ['Delivered Beyond Scope', 'What It Means for Aesthetic Renewal'],
  [
    ['40+ Qualified Lead Opportunities', 'Not raw form fills. Qualified opportunities generated and routed to your team, representing real booked revenue potential across both locations.'],
    ['Meta Ads Built and Managed for Two Locations', 'Full campaign lifecycle across Facebook and Instagram: strategy, creative, audience testing, and ongoing optimization, structured separately for Medford and Cinnaminson so each location competes in its own market.'],
    ['Organic Posting Materials', 'Professionally built organic content assets so the brand stays present between paid campaigns and the ad spend is not carrying the entire practice.'],
    ['Membership Program', 'A complete membership structure built for your team: tiers, pricing logic, positioning, and the enrollment conversation. Recurring revenue that compounds every month it stays live.'],
    ['Package Architecture', 'Package and upsell structure designed to raise average transaction value and lock in repeat visits instead of one-off treatments.'],
    ['Sales Collateral and Team Enablement', 'The written materials your front desk and providers use to present memberships and packages without discounting, guessing, or improvising.'],
  ]));
children.push(spacer(120));
children.push(p('Said plainly: you paid for a diagnosis and a roadmap. You also received lead generation, paid media management across two locations, a membership program, a package architecture, and the collateral to sell all of it. That is the difference between a consultant and a partner.'));

children.push(new Paragraph({ children: [new PageBreak()] }));

// 04 THE LIBRARY
children.push(sectionHead('04', 'The Luxora Library'));
children.push(p('This is what the other firms you are evaluating cannot put on the table. Agencies sell traffic. We hand you the operating system that converts and keeps it. Every playbook below is a written, trainable framework your team owns permanently.'));
children.push(spacer(60));

children.push(subHead('Revenue and Retention'));
children.push(bullet('Structure, tiers, pricing logic, enrollment scripts, and retention mechanics for predictable recurring revenue.', 'Membership Playbook: '));
children.push(bullet('Bundle design, upsell sequencing, and the conversation that raises average transaction value without discounting.', 'Package and Upsell Playbook: '));
children.push(bullet('The frameworks that turn a first-time patient into a multi-year patient, measured and managed.', 'LTV Sales Playbook: '));
children.push(bullet('Reactivation and referral systems that pull revenue out of the patient list you already own.', 'Patient Reactivation and Referral Frameworks: '));

children.push(subHead('Sales and Team Performance'));
children.push(bullet('The consult-to-close system for every client-facing role, from the first phone call to the treatment plan presentation.', 'Conversion Playbook: '));
children.push(bullet('Scripted, trainable front desk and sales conversations built around physician-led positioning.', 'Sales and Consultation Playbooks: '));
children.push(bullet('Pay structures that reward the behavior you actually want without eroding margin.', 'Compensation and Incentive Playbook: '));
children.push(bullet('A behavioral fit assessment used to hire the right people the first time.', 'Culture Index and Hiring Support: '));

children.push(subHead('Operations and Profit'));
children.push(bullet('Documented processes for front desk, sales, and marketing so results are never dependent on one person.', 'SOP Playbook and Master Index: '));
children.push(bullet('Turning retail from an afterthought into a measurable margin line.', 'Retail as a Profit Center Playbook: '));
children.push(bullet('The numbers that matter, how to read them, and what to do when they move.', 'KPI Reference Playbook: '));
children.push(bullet('Utilization and pricing frameworks that make expensive equipment pay for itself.', 'Laser ROI Playbook: '));

children.push(subHead('Reputation and Market Presence'));
children.push(bullet('Systematized review generation and response so credibility shows up where patients are looking.', 'Reputation Engine Playbook: '));
children.push(bullet('The in-practice event system that drives concentrated revenue and referrals in a single evening.', 'Celebration Event Playbook: '));
children.push(bullet('Sourcing and structuring local partnerships that send qualified patients without ad spend.', 'Strategic Partnership Frameworks: '));
children.push(bullet('A secret shopper program that shows you exactly what your patients experience.', 'Confidential Experience Assessment: '));

children.push(subHead('Execution and Accountability'));
children.push(bullet('The sequenced implementation plan, with owners and deadlines.', '90-Day Transformation Roadmap: '));
children.push(bullet('The working document that keeps implementation honest between calls.', '90-Day Client Action Checklist: '));
children.push(bullet('Optional add-on for practices expanding into peptides, GLP-1s, hormones, or wellness.', 'Longevity Playbook: '));
children.push(spacer(120));
children.push(p('No competitor in this evaluation is bringing a library. They are bringing a media buy.', { italics: true, color: GREY }));

// 05 OPTIONS
children.push(new Paragraph({ children: [new PageBreak()] }));
children.push(sectionHead('05', 'Moving Forward: Three Ways to Continue'));
children.push(p('Three levels of partnership. Same team, same standards, different depth of involvement. Choose based on how much you want your own team to carry versus how much you want us to carry.'));
children.push(spacer(100));

children.push(optionCard(
  'Option A',
  'Executive Growth Partnership',
  '$8,000',
  'per month',
  'Everything Luxora offers, with Dr. Hyder working directly with me.',
  [
    'One-on-one strategic consulting with Dr. Hyder, direct and unfiltered, not routed through an account manager.',
    'Quarterly in-person visit to the practice: floor observation, team training delivered live, and leadership working sessions on site.',
    'Full access to the entire Luxora Library, implemented with your team rather than handed over.',
    'Meta ads management across both locations, including strategy, creative, testing, and optimization.',
    'Membership, package, and LTV frameworks actively managed and optimized, not left static.',
    'CRM and AI follow-up oversight so speed to lead and reactivation run without manual effort.',
    'KPI dashboard and reporting by location, reviewed with you every month.',
    'Dedicated operations oversight: one point of accountability across every vendor, deliverable, and deadline.',
    'Weekly calls, plus ongoing Slack access to the Luxora team.',
    'Priority scheduling on everything.',
  ],
  'A physician-owner who wants a true executive partner and intends to take meaningful market share across both locations.',
  true
));
children.push(spacer(200));

children.push(optionCard(
  'Option B',
  'Implementation Partnership',
  '$5,000',
  'per month',
  'Same level of back-end support. We train your team to implement the playbooks.',
  [
    'Full access to the entire Luxora Library, delivered as structured training to your team.',
    'Biweekly strategy and accountability calls with your leadership and staff.',
    'Hands-on staff sales training on the Conversion, Membership, and Package playbooks.',
    'SOP development and documentation so the systems survive turnover.',
    'Membership and package architecture maintained and refined as the practice grows.',
    'KPI dashboard and reporting, reviewed on every call.',
    'Dedicated operations oversight and meeting-to-action-item tracking.',
    'Ongoing Slack access to the Luxora team.',
  ],
  'A practice that wants the full Luxora system installed and owned internally, with our team behind the build.',
  false
));
children.push(spacer(200));

children.push(optionCard(
  'Option C',
  'Acquisition Management',
  '$3,000',
  'per month, plus ad spend',
  'We run the ads. You keep the machine we already built.',
  [
    'Full Meta ads management across both locations: strategy, creative, audience testing, and optimization.',
    'Campaign structure built separately for Medford and Cinnaminson so each location competes in its own market.',
    'Monthly strategy session reviewing performance, spend, and next-cycle direction.',
    'Ongoing Slack support for questions between sessions.',
    'Lead flow reporting so you can see exactly what the spend is producing.',
  ],
  'A practice that wants the lead engine running consistently and will handle internal execution on its own.',
  false
));
children.push(spacer(160));
children.push(p('Ad spend is paid directly to the platforms and is separate from the management investment in every option above.', { size: 19, italics: true, color: GREY }));

// 06 ADD-ONS
children.push(new Paragraph({ children: [new PageBreak()] }));
children.push(sectionHead('06', 'Optional Add-Ons'));
children.push(p('The following can be layered onto any option above. These are delivered by a dedicated concierge team of strategists, account managers, and specialists working fully under the Luxora brand, so you get agency-scale execution with a single point of accountability.'));
children.push(spacer(60));
children.push(makeTable([2500, 5060, 1800],
  ['Add-On', 'What It Includes', 'Investment'],
  [
    ['SEO and Organic Search Growth', 'Ongoing search engine optimization to build long-term organic visibility and reduce dependence on paid ads.', 'Scope dependent'],
    ['Local SEO, GEO, and Google Maps', 'Google Business Profile and local map pack optimization so each location ranks for nearby high-intent searches.', 'Scope dependent'],
    ['Organic Social Content and Posting', 'Consistent, professionally managed organic content across channels to build presence between campaigns.', 'Scope dependent'],
    ['Google Ads (PPC)', 'Search and display campaign management to capture high-intent local searches for Aesthetic Renewal\u2019s services.', 'Scope dependent'],
    ['Website Development, Hosting, and Management', 'New authority website build or ongoing site management, plus managed hosting.', 'Scope dependent'],
  ]));
children.push(spacer(120));
children.push(p('Pricing for add-ons is determined by level of need. We will scope only what moves the number and will tell you plainly when something is not worth buying yet.'));

// 07 WHY LUXORA
children.push(sectionHead('07', 'Why Luxora'));
children.push(p('You are evaluating three firms. Here is the honest difference.'));
children.push(spacer(60));
children.push(makeTable([3120, 3120, 3120],
  ['', 'A Typical Agency', 'The Luxora Collective'],
  [
    ['Starting point', 'Sells you traffic on day one.', 'Finds the revenue already in the building before asking you to spend more.'],
    ['What you get', 'Leads, for as long as you pay.', 'Leads, plus the systems, playbooks, and trained team that convert and retain them.'],
    ['Ownership', 'The knowledge stays with the vendor.', 'Knowledge transfer at every step. Your team owns it permanently.'],
    ['Accountability', 'An account manager and a report.', 'One point of accountability across every vendor, deliverable, and deadline.'],
    ['Track record here', 'Starting from zero.', 'Already delivered, already above scope, already knows your market and your positioning.'],
  ]));
children.push(spacer(140));
children.push(p('The other two firms would spend the first ninety days learning what we already know about Aesthetic Renewal. We are past that. The blueprint is built, the ads are live, the memberships and packages exist, and the leads are already flowing. Continuing with Luxora is not a start. It is a continuation with compounding returns.'));

// 08 NEXT STEPS
children.push(sectionHead('08', 'Next Steps'));
children.push(p('We know a decision is coming this week.'));
children.push(bullet('Select Option A, B, or C, and identify any add-ons worth scoping.'));
children.push(bullet('We issue the agreement and lock the onboarding start date.'));
children.push(bullet('Priority scheduling for the Luxora and execution teams begins immediately on signature.'));
children.push(bullet('No pause in ad performance. The campaigns already running stay running.'));
children.push(spacer(180));
children.push(new Table({
  columnWidths: [TW],
  width: { size: TW, type: WidthType.DXA },
  borders: {
    top: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
    bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
    left: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
    right: { style: BorderStyle.SINGLE, size: 6, color: GOLD },
  },
  rows: [new TableRow({ children: [new TableCell({
    width: { size: TW, type: WidthType.DXA },
    shading: { type: ShadingType.CLEAR, fill: DARK, color: 'auto' },
    margins: { top: 260, bottom: 260, left: 240, right: 240 },
    children: [
      new Paragraph({ spacing: { after: 100 }, alignment: AlignmentType.CENTER, children: [new TextRun({
        text: 'READY WHEN YOU ARE', font: FONT, size: 26, bold: true, color: 'FFFFFF', characterSpacing: 60 })] }),
      new Paragraph({ spacing: { after: 0, line: 276 }, alignment: AlignmentType.CENTER, children: [new TextRun({
        text: 'The spa you imagined is still in there. So are you. Whatever combination makes sense for Aesthetic Renewal, we are ready to move fast and keep delivering.',
        font: FONT, size: 20, italics: true, color: 'FFFFFF' })] }),
    ],
  })] })],
}));
children.push(spacer(240));
children.push(p('Bethany Ward', { bold: true, size: 21, after: 20 }));
children.push(p('Co-Founder & CEO, The Luxora Collective', { size: 19, color: GREY, after: 20 }));
children.push(p('theluxoracollective.co', { size: 19, color: GOLD, after: 0 }));

// ---------- document ----------
const doc = new Document({
  numbering: {
    config: [{
      reference: 'lux-bullets',
      levels: [{
        level: 0,
        format: LevelFormat.BULLET,
        text: '\u2022',
        alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 300, hanging: 200 } },
                 run: { color: GOLD, font: FONT } },
      }],
    }],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 },
      },
    },
    footers: {
      default: new d.Footer({
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          border: { top: { style: BorderStyle.SINGLE, size: 4, color: LIGHT } },
          spacing: { before: 120 },
          children: [new TextRun({
            text: 'CONFIDENTIAL   |   THE LUXORA COLLECTIVE   |   PREPARED FOR AESTHETIC RENEWAL MED SPA',
            font: FONT, size: 15, color: GREY, characterSpacing: 20 })],
        })],
      }),
    },
    children,
  }],
});

Packer.toBuffer(doc).then(b => {
  fs.writeFileSync('/home/claude/Luxora_Aesthetic_Renewal_Growth_Partnership_Proposal.docx', b);
  console.log('written', b.length);
});

