const fs = require('fs');
const d = require('docx');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, ShadingType, AlignmentType, HeadingLevel, BorderStyle,
  PageBreak, LevelFormat, convertInchesToTwip
} = d;

const GOLD = 'A8894F';
const DARK = '1A1A1A';
const GREY = '5C5C5C';
const CREAM = 'F5F2EC';
const LIGHT = 'EDEAE3';

const FONT = 'Calibri';

// ---------- helpers ----------
const rule = (color = GOLD, size = 8) => new Paragraph({
  spacing: { before: 60, after: 200 },
  border: { bottom: { style: BorderStyle.SINGLE, size, color } },
});

const p = (text, opts = {}) => new Paragraph({
  spacing: { after: opts.after ?? 140, line: 276 },
  alignment: opts.align,
  indent: opts.indent,
  children: [new TextRun({
    text,
    font: FONT,
    size: opts.size ?? 21,
    bold: opts.bold ?? false,
